import * as Cloudflare from '@alchemy.run/cloudflare'
import * as Alchemy from 'alchemy'
import { retain } from 'alchemy/RemovalPolicy'
import { Effect } from 'effect'

/**
 * The team's scratch site: docs/site's pages plus pinned visualization libraries, served as static assets from one
 * Worker with one stable URL. `worker.ts` adds the only server code, login-free page comments in D1 (`/api/comments`),
 * through Drizzle (`schema.ts`, migrations generated by drizzle-kit into `migrations/`). Deployed by .github/workflows/site.yml on every push to main that touches docs/site, or straight from a
 * working copy with `bun run site:deploy`, no commit needed.
 *
 * State lives in a named Cloudflare state store (`alchemy-state-store-ethmumbai`), not the account's shared default
 * store, so this project never touches other projects' Alchemy state.
 */
export default Alchemy.Stack(
  'EthMumbaiSite',
  { providers: Cloudflare.providers(), state: Cloudflare.state({ name: 'ethmumbai' }) },
  Effect.gen(function* () {
    // Comments are the team's feedback: a stack teardown keeps them.
    const comments = yield* Cloudflare.D1.Database('CommentsDatabase', { migrations: 'migrations' }).pipe(retain())
    const site = yield* Cloudflare.Website.StaticSite('Site', {
      name: 'eth-mumbai-site',
      main: 'worker.ts',
      env: { DB: comments },
      command: 'bun build.ts',
      outdir: 'dist',
      memo: false,
      workersDev: true,
      compatibility: { date: '2026-10-19' },
    })
    return { url: site.url.as<string>() }
  }),
)
